/**
 * 多卷轴配置
 */
let MulSlotCfg = {
    maxSlotCnt:8,       // 最大slot数量
    currSlotCnt:1,      // 当前slot数量
    unitSlotRowCnt:4,   // 单个slot 行数
    unitSlotColCnt:5,   // 单个slot 列数
    aSlotSymbolCnt:20,  // 一个slots 的symbol个数
}

/**
 * 幸运蜜蜂slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        allReels:[], // 保存所有reel组件 前5个reel普通游戏用 后40个reel免费游戏用
    },

    onLoad() {
        this._super();
    },

    /**
     * 创建卷轴
     * @override
     * @param col
     * @param row
     */
    createReels:function(col,row){
        let reelCmp = this._cfg.scripts.Reels
        // 普通游戏卷轴
        let reelIndex = 0;
        for(let i=0; i<5; i++) {
            let node = cc.find(`reels/reel${i+1}`, this.node);
            let scp = node.addComponent(reelCmp)
            scp.Init(reelIndex++, row, this._topAniNode);
            this.allReels.push(scp)
        }
        // 免费游戏卷轴
        for(let i=0; i<8; i++) {
            for(let j=0; j<5; j++) {
                let node = cc.find(`slot_list/slots${i+1}/reel${j+1}`, SlotsFacade.mainPanel.slots_free);
                let scp = node.addComponent(reelCmp)
                scp.Init(reelIndex++, row, this._topAniNode);
                this.allReels.push(scp)
            }
        }
    },
    //重写
    StartMove: function () {
        this._bStopRightnow = null
        this._gameInfo = null
        SlotsFacade.flowCtrl.startMove();
        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this.getCurReels());  //Changed ...

        //设置停止时间
        //就是收到结果后，如果多少秒会开始停止
        this._stopTime = this.GetStopTime();
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm()
        }
    },

    //重写
    onMsgSpine: function (msg) {
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 返回当前有效得reels 请求消息前调用
     */
    getCurReels () {
        return this._reels;
    },

    /**
     * 设置 reels
     * @param isFree 是否是免费中
     * @param slotCnt slots 个数
     */
    setReels(isFree, slotCnt) {
        this._topAniNode.removeAllChildren(true);
        SlotsFacade.slots.resetAllSymbol();
        if(isFree) {
            this._reels = this.allReels.slice(5, (slotCnt+1)*5);
            MulSlotCfg.currSlotCnt = slotCnt;
        }else {
            this._reels = this.allReels.slice(0, 5);
            MulSlotCfg.currSlotCnt = 1;
        }
    },

    /**
     * 转换下标
     */
    transferIdx(idx) {
        idx = idx-1;
        let col = Math.floor(idx/MulSlotCfg.aSlotSymbolCnt)*MulSlotCfg.unitSlotColCnt + idx%MulSlotCfg.unitSlotColCnt;
        let row = MulSlotCfg.unitSlotRowCnt - 1 - Math.floor(idx%MulSlotCfg.aSlotSymbolCnt/MulSlotCfg.unitSlotColCnt);
        return {col:col, row:row};
    },

    /**
     * @override
     * @param {*} idx 服务器symbol下标1开始
     */
    GetSymbolByIdx(idx){
        let idxInfo = this.transferIdx(idx);
        return this._reels[idxInfo.col].GetSymbolByRow(idxInfo.row);
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx
     */
    getIdxGlobalPos(idx) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let pos = reel.GetSymbolPosByRow(idxInfo.row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 设置symbol数据
     * @param cards
     * @constructor
     */
    SetSlotsResult:function(cards){
        let reelResults = [];
        for(let i=0; i<MulSlotCfg.currSlotCnt; i++) {
            let startIndex = i*MulSlotCfg.unitSlotColCnt*MulSlotCfg.unitSlotRowCnt;
            let endIndex = startIndex + MulSlotCfg.unitSlotColCnt*MulSlotCfg.unitSlotRowCnt;
            for(let j=startIndex; j<endIndex; j++){
                let col = i*MulSlotCfg.unitSlotColCnt + j % MulSlotCfg.unitSlotColCnt;
                let res = {};
                res.sid = cards[j];
                if(!reelResults[col]) {
                    reelResults[col] = [];
                }
                reelResults[col].unshift(res);
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    /**
     * @override
     * @param {*} cards
     */
    SetReelStateInfo:function(cards){
        if(MulSlotCfg.currSlotCnt != 1) {
            return;
        }
        this._super(cards);
    },

    /**
     * 播放scatter 中奖动画
     */
    async playTriggerAni(indexs) {
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 重置所有symbol
     */
    resetAllSymbol() {
        if(!this._reels) {
            return;
        }
        for(let reel of this._reels) {
            for(let s of reel._symbols) {
                s.StartMove();
            }
        }
    },

    /**
     * @override
     * @param {*} reelIdx
     */
    GetReelStopInter(reelIdx){
        let nIter = this._cfg.reelStopInter || 0.6
        return reelIdx%MulSlotCfg.unitSlotColCnt*nIter;
    },

    /**
     * 显示中奖路线
     * @override
     */
    ShowWinTrace:function(){
        let allWinIdx = [];
        let needPlayGoldLionSound = false;
        //中奖位置
        let zjLuXian = SlotsFacade.dm.getZjLuXian();
        let cards = SlotsFacade.dm.getCards();
        for(let i = 0; i < zjLuXian.length; i++){
            let item = zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1;
                if(!needPlayGoldLionSound && cards[item.indexs[idx]-1]) {
                    needPlayGoldLionSound = true;
                }
            }
        }
        let skipBorderAniIdxs = [];
        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
            skipBorderAniIdxs = this._gameInfo.scatterZJLuXian.indexs.concat();
        }

        if(needPlayGoldLionSound && SlotsFacade.dm.freeSlotsInfo) {
            SlotsFacade.soundMgr.playEffect("H1");
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation();
                if(!skipBorderAniIdxs.includes(Number(key))) {
                    symbol.ShowKuang();
                }
            }
        }
    },

    /**
     * 切换到普通游戏状态
     */
    toNormalState() {
        SlotsFacade.character.toNormalState();
        SlotsFacade.diamondCollect.show();
        SlotsFacade.mainPanel.jpNode.active = true;
        cc.find("reels", this.node).active = true;
        this._topAniNode.scale = 1;
        this.setTopAniNodeScale(1);
    },

    /**
     * 免费游戏
     */
    toFreeState(scale) {
        scale = scale || 0.5;
        SlotsFacade.character.toFreeState();
        SlotsFacade.diamondCollect.hide();
        SlotsFacade.mainPanel.jpNode.active = false;
        cc.find("reels", this.node).active = false;
        this.setTopAniNodeScale(scale);
    },

    setTopAniNodeScale(scale) {
        this._topAniNode.scale = scale;
    }
});
