cc.Class({
    extends: cc.Component,

    properties: {
        role:sp.Skeleton,
    },

    onLoad() {
    },

    start() {
    },

    /**
     * 转到普通状态
     */
    toNormalState() {
        this.role.node.active = true;
    },

    /**
     * 转到免费状态
     */
    toFreeState() {
        this.role.node.active = false;
    },
});
