/**
 * 幸运蜜蜂卷轴
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    /**
     * @override
     * @constructor
     */
    StartMove() {
        this._super();
    },

    /**
     * 在父类方法的基础上  添加停止音效处理逻辑
     * @override
     */
    playReelStop() {
        this._super();

        // 免费多卷轴中特殊处理
        if(!this._reelState || this._reelState.length < 1) {
            let reelIdx = this.GetReelIdx();
            // 停止音效
            if(reelIdx < 10) {
                let goldId = SlotsFacade.dm.getGameCfg().bonusId;
                let hasGoldLion = false;
                let cards = SlotsFacade.dm.freeSlotsInfo.cards;
                for(let i=0; i<cards.length; i++) {
                    if(i%5 == reelIdx%5 && cards[i] == goldId) {
                        hasGoldLion = true;
                        break;
                    }
                }
                if(hasGoldLion) {
                    SlotsFacade.soundMgr.playEffect("reelgold");
                }else {
                    SlotsFacade.soundMgr.playEffect("reelstop");
                }
            }
        }
    }
});
