
cc.Class({
    extends: cc.Component,

    properties: {
        red:cc.Node,
        purple:cc.Node,
        blue:cc.Node,
        spine_red:sp.Skeleton,
        spine_purple:sp.Skeleton,
        spine_blue:sp.Skeleton,
        spine_path:sp.Skeleton,

        tips_node:cc.Node,
        tip_lock:cc.Node,
        tip_unlock:cc.Node,
        btn_unlock:cc.Node,
        spine_unlock_eff:sp.Skeleton,

        _isOpen:false,   // 是否打开收集
        _data:null,
    },

    onLoad() {
        this._data = {
            blue:0,
            purple:0,
            red:0,
        }
    },

    start() {
        this.updateDiamond();
        this._initListener();
        this.showCollect(true);
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.updateDiamond();
            this.showCollect(false);
        },this);

        this.btn_unlock.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(!this._isOpen) {
                this._openCollect();
            }
        });
    },

    /**
     * 打开收集
     */
    _openCollect() {
        // 如果已经打开收集 返回
        if(this._isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        // 如果是自动模式 返回
        if(cc.vv.gameData.GetAutoModelTime() > 0) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 显示收集界面
     * @param isInit 是否是初始化
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            this.tip_unlock.active = true;
            this.tip_lock.active = false;
        }else {
            this.tip_unlock.active = false;
            this.tip_lock.active = true;
        }
        if(!isInit && this._isOpen != boo) {
            SlotsFacade.soundMgr.playEffect("JPunlock");
            this.spine_unlock_eff.node.active = true;
            this.spine_unlock_eff.setAnimation(0, "BetUp1_Intro", false);
            this.spine_unlock_eff.setCompleteListener(()=>{
                this.spine_unlock_eff.setCompleteListener(null);
                this.spine_unlock_eff.node.active = false;
            });
        }
        this._isOpen = boo;
    },

    /**
     * 更新花朵信息
     */
    updateDiamond() {
        let info = SlotsFacade.dm.getCurrDiamondInfo();
        this._data.blue = info.blue.freeCnt;
        this._data.purple = info.purple.freeCnt;
        this._data.red = info.red.freeCnt;
        this.red.getChildByName("label").getComponent(cc.Label).string = this._data.red.toString();
        this.purple.getChildByName("label").getComponent(cc.Label).string = this._data.purple.toString();
        this.blue.getChildByName("label").getComponent(cc.Label).string = this._data.blue.toString();
    },

    /**
     * 收集钻石
     * @param percent
     */
    async collectDiamond() {
        if(!this.node.active) {
            return;
        }
        let spinData = SlotsFacade.dm.getSpinData();
        if(!spinData.currDiamondIdx) {
            return;
        }
        let diamondId = spinData.resultCards[spinData.currDiamondIdx-1];
        let cfgItem = {
            "301":{diamondName:"blue", collect_node:this.blue, spine:this.spine_blue, animation:"D_blue", count_animation:"D_blue_ad", path_animation:"path_blue"},
            "302":{diamondName:"purple",collect_node:this.purple, spine:this.spine_purple, animation:"D_purple", count_animation:"D_purple_ad",path_animation:"path_green"},
            "303":{diamondName:"red",collect_node:this.red, spine:this.spine_red, animation:"D_red", count_animation:"D_red_ad",path_animation:"path_red"},
        }[diamondId];
        if(!cfgItem) {
            console.log("钻石数据出错", spinData.currDiamondIdx);
        }
        this._data[cfgItem.diamondName] += 1;
        SlotsFacade.soundMgr.playEffect("diamond");
        let startPos = SlotsFacade.slots.getIdxGlobalPos(spinData.currDiamondIdx);
        startPos = this.node.convertToNodeSpaceAR(startPos);
        let endPos = cfgItem.collect_node.getChildByName("icon_diamond").convertToWorldSpaceAR(cc.v2(0,0));
        endPos = this.node.convertToNodeSpaceAR(endPos);
        // 播放钻石动画
        let diamondSpine = cfgItem.spine;
        diamondSpine.node.active = true;
        diamondSpine.node.position = startPos;
        diamondSpine.setAnimation(0, cfgItem.animation, false);
        // 移动钻石
        cc.tween(diamondSpine.node)
            .delay(1.8)
            .call(()=>{
                // 播放移动路径特效
                cc.tween(this.node)
                    .delay(0.15)
                    .call(()=>{
                        this.spine_path.node.active = true;
                        this.spine_path.node.position = startPos;
                        this.spine_path.setAnimation(0, cfgItem.path_animation, false);
                    })
                    .start();
            })
            .to(0.5, {position:endPos}, {easing:"backIn"})
            .call(()=>{
                // 播放次数动画
                let numberEff = cfgItem.collect_node.getChildByName("spine_numb_effect").getComponent(sp.Skeleton);
                numberEff.node.active = true;
                numberEff.setAnimation(0, cfgItem.count_animation, false);
                numberEff.setCompleteListener(()=>{
                    numberEff.setCompleteListener(null);
                    numberEff.node.active = false;

                    let label = cfgItem.collect_node.getChildByName("label");
                    cc.tween(label)
                        .to(0.3, {scale:1.5})
                        .call(()=>{
                            label.getComponent(cc.Label).string = this._data[cfgItem.diamondName]+"";
                        })
                        .to(0.2, {scale:1})
                        .start();
                })
            })
            .delay(0.5)
            .call(()=>{
                diamondSpine.node.active = false;
                this.spine_path.node.active = false;
            })
            .start();
        await SlotsFacade.delayTime(2.6);
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
        this.updateDiamond();
    }
});
