/**
 * 主场景资源
 */
cc.Class({
    extends: cc.Component,

    properties:{
    },

    onLoad() {
        this.bg = this.node.getChildByName("bg");
        this.popup_node = this.node.getChildByName("popup_node");
        this.wheel_node = this.node.getChildByName("wheel_node");
        this.transition_node = this.node.getChildByName("transition_node");
        this.jpNode = this.node.getChildByName("LMSlots_PrizePool_1");
        this.top_node = this.node.getChildByName("top_node");

        this.slots = this.node.getChildByName("slots");
        this.slots_free = this.slots.getChildByName("slots_free");
        this.character_node = this.slots.getChildByName("character_node");
        this.diamond_collect = this.slots.getChildByName("diamond_collect");
        this.showBg(0);
    },

    /**
     * 显示免费背景
     * type 背景类型 0-普通游戏 1-respin 2-免费
     */
    showBg(type) {
        if(!type) {
            type = 0;
        }
        this.bg.getComponent("ImgSwitchCmp").setIndex(type);
    },

    /**
     * 幕布转场动画
     * @param {*} type 1 狮子动画   2 闪光动画 3 带颜色的闪光动画
     * @param diamondType 钻石的类型，当type等于3时需要传这个字段免费中专用 取值范围 2,3,4中
     * @returns {Promise<void>}
     */
    async showSceneTransition(type, diamondType) {
        type = type || 1;
        let aniCfg = {
            [1]:{time:1.5, aniName:"skill", soundName:"ngtowheel"},
            [2]:{time:0.7, aniName:"TY_guochang", soundName:"wheeltofg"},
            [3]:{time:0.7, aniName:"", soundName:"wheeltofg"},
        }[type];
        if(!aniCfg) {
            console.log("#showSceneTransition#动画类型错误")
            return;
        }
        if(type == 3) {
            aniCfg.aniName = `FG_D_${["blue", "green", "red"][diamondType-2]}`;
        }
        SlotsFacade.soundMgr.playEffect(aniCfg.soundName);
        let spine = this.transition_node.getChildByName(`spine${type}`).getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, aniCfg.aniName, false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
        await SlotsFacade.delayTime(aniCfg.time);
    },
 })