/**
 * 弹窗管理器
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node,
        bg_dark:cc.Node,
    },

    onLoad() {
    },

    showBg(boo) {
        this.bg.active = boo;
    },

    showBgDark(boo) {
        this.bg_dark.active = boo;
    },

    /**
     * 显示赢取免费次数
     * @param slotCnt 卷轴数量
     * @param freeCnt 免费次数
     * @returns {Promise<void>}
     */
    async showWinFreeCnt(slotCnt, freeCnt) {
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_cnt");
        panel.active = true;
        panel.scale = 2;

        // 背景
        let bg = panel.getChildByName("bg").getComponent("ImgSwitchCmp");
        bg.setIndex(slotCnt-1);
        // 标题
        let title = panel.getChildByName("title").getComponent("ImgSwitchCmp");
        title.setIndex(slotCnt-1);
        // 文本
        let label = panel.getChildByName("label");
        label.getComponent(cc.Label).string = freeCnt.toString();

        // 弹框动画
        await new Promise(res=>{
            cc.tween(panel)
                .to(0.6, {scale:1}, {easing:"backOut"})
                .delay(1.5)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.showBg(false);
                    panel.active = false;
                    res();
                })
                .start();
        })
    },

    /**
     * 显示赢取免费游戏金币
     * @param {number} goldNumb
     */
    async showWinFreeGold(goldNumb) {
        SlotsFacade.soundMgr.playEffect("fgend");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_coin");
        panel.active = true;
        panel.scale = 2;
        // 文本
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);
        label.active = true;
        label.scale = 0;
        cc.tween(label)
            .to(0.5, {scale:1})
            .start();
        // 按钮
        let okBtn = panel.getChildByName("btn_ok");
        okBtn.scale = 0;
        okBtn.active = true;
        cc.tween(okBtn)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        // 弹框动画
        cc.tween(panel)
            .to(0.6, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.6);
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("button");
                okBtn.off(cc.Node.EventType.TOUCH_END);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },
})