/**
 * slot位置配置
 */
let SlotsPosCfg = {
    [1]: {
        posArr:[cc.v2(0, 0)],
        scale:1
    },
    [2]: {
        posArr:[cc.v2(0, 0), cc.v2(0, 330)],
        scale:0.7
    },
    [3]: {
        posArr:[
            cc.v2(-176, 0), cc.v2(176, 0),
            cc.v2(0, 230)
        ],
        scale:0.5
    },
    [4]: {
        posArr:[
            cc.v2(-176, 0), cc.v2(176, 0),
            cc.v2(-176, 230), cc.v2(176, 230)
        ],
        scale:0.5
    },
    [5]: {
        posArr:[
            cc.v2(-176, 0), cc.v2(176, 0),
            cc.v2(-176, 230), cc.v2(176, 230),
            cc.v2(0, 460),
        ],
        scale:0.5
    },
    [6]: {
        posArr:[
            cc.v2(-176, 0), cc.v2(176, 0),
            cc.v2(-176, 230), cc.v2(176, 230),
            cc.v2(-176, 460), cc.v2(176, 460),
        ],
        scale:0.5
    },
    [7]: {
        posArr:[
            cc.v2(-176, 0), cc.v2(176, 0),
            cc.v2(-176, 230), cc.v2(176, 230),
            cc.v2(-176, 460), cc.v2(176, 460),
            cc.v2(0, 690),
        ],
        scale:0.5
    },
    [8]: {
        posArr:[
            cc.v2(-176, 0), cc.v2(176, 0),
            cc.v2(-176, 230), cc.v2(176, 230),
            cc.v2(-176, 460), cc.v2(176, 460),
            cc.v2(-176, 690),cc.v2(176, 690),
        ],
        scale:0.5
    },
}

cc.Class({
    extends: cc.Component,

    properties: {
        slot_list:cc.Node,
        free_count:cc.Node,
        collect_node:cc.Node,
        spine_add_slot_effect:sp.Skeleton,
        spine_collect_effect:sp.Skeleton,
        goldLionCnt:cc.Label,
        tips:cc.Node,
        particle:cc.Node,

        _isEnter:false,
        _slotCnt:2,
    },

    onLoad() {
    },

    show() {
        this.slot_list.opacity = 0xff;
        this.slot_list.active = true;
        this.free_count.active = true;
        this.collect_node.active = true;
    },

    hide() {
        this.slot_list.active = false;
        this.free_count.active = false;
        this.collect_node.active = false;
        for(let i=0; i<8; i++) {
            let slot = cc.find(`slots${i+1}`, this.slot_list);
            slot.active = false;
            slot.getChildByName("reels_bg").active = false;
        }
    },

    /**
     * 进入免费
     * @param isReconnect
     * @returns {Promise<void>}
     */
    async enter(isReconnect) {
        if(this._isEnter) {
            return;
        }
        SlotsFacade.freeGame.hide();
        SlotsFacade.soundMgr.playBgm("fgbgm");
        let freeInfo = SlotsFacade.dm.freeInfo;
        this._isEnter = true;
        this._slotCnt = freeInfo.slotCnt;
        this.show();
        this.showSlot(freeInfo.slotCnt);
        this.updateCollect(true);
        this.updateFreeCnt(true);
        SlotsFacade.slots.toFreeState(SlotsPosCfg[freeInfo.slotCnt].scale);
        if(!isReconnect) {
            await SlotsFacade.popup.showWinFreeCnt(freeInfo.slotCnt, freeInfo.freeCnt);
        }
    },

    /**
     * 退出免费
     * @returns {Promise<void>}
     */
    async exit() {
        if(!this._isEnter) {
            return;
        }
        this.hide();
        SlotsFacade.slots.setReels(false);
        this._isEnter = false;
    },

    /**
     * 更新收集界面
     */
    updateCollect(updateTips) {
        updateTips = updateTips || false;
        let freeInfo = SlotsFacade.dm.freeInfo;
        this.goldLionCnt.string = freeInfo.goldLionCnt + "";
        if(updateTips) {
            let slotCntArr = [2, 3, 4, 6, 8];
            slotCntArr.forEach(v=>{
                let tip = this.tips.getChildByName(`tip${v}`);
                if(tip) {
                    tip.active = v > this._slotCnt;
                }
            })
        }
    },

    /**
     * 更新免费次数
     * @param updateUi
     * @returns {Promise<void>}
     */
    updateFreeCnt(updateUi) {
        updateUi = updateUi || false;
        if(updateUi) {
            let index = SlotsFacade.dm.freeInfo.type - 2;
            let bg = this.free_count.getChildByName("bg").getComponent("ImgSwitchCmp");
            bg.setIndex(index);
            let title = this.free_count.getChildByName("title").getComponent("ImgSwitchCmp");
            title.setIndex(index);
            let labelFont = this.free_count.getChildByName("label").getComponent("LabelSwitchCmp");
            // labelFont.setIndex(index);
            if(SlotsFacade.dm.freeInfo.type == 5) {
                title.node.x = -55;
                bg.node.y = -3;
            }else {
                title.node.x = 0;
                bg.node.y = 0;
            }
        }
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();
        let label = this.free_count.getChildByName("label").getComponent(cc.Label);
        label.string = `${total-rest}/${total}`;
    },

    /**
     * 显示slots背景
     * @param slotCnt
     */
    showSlot(slotCnt) {
        // 显示slot
        SlotsFacade.slots.setReels(true, slotCnt);
        for(let i=0; i<slotCnt; i++) {
            let slot = cc.find(`slots${i+1}`, this.slot_list);
            slot.active = true;
            slot.getChildByName("reels_bg").active = true;
        }

        let tip = cc.find("tips/add_free_tip", this.collect_node);
        tip.active = slotCnt <= 4;

        // 设置 slot 位置
        let posCfg = SlotsPosCfg[slotCnt];
        if(posCfg) {
            for(let i=0; i<posCfg.posArr.length; i++) {
                let slot = cc.find(`slots${i+1}`, this.slot_list);
                slot.position = posCfg.posArr[i];
                slot.scale = posCfg.scale;
            }
            SlotsFacade.slots.setTopAniNodeScale(posCfg.scale);
        }else {
            console.log("slot 数量异常", slotCnt);
        }
    },

    /**
     * 收集金色狮子
     * @returns {Promise<void>}
     */
    async collect() {
        let cfg = SlotsFacade.dm.getGameCfg();
        let freeInfo = SlotsFacade.dm.freeInfo;
        let freeSlotsInfo = SlotsFacade.dm.freeSlotsInfo;
        let topNode = SlotsFacade.mainPanel.top_node;
        if(freeSlotsInfo.cards.length < 1) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("collectgold");
        // 收集
        let endPos = this.collect_node.convertToWorldSpaceAR(cc.v2(0,0));
        endPos = topNode.convertToNodeSpaceAR(endPos);
        for(let i=0; i<freeSlotsInfo.cards.length; i++) {
            let c = freeSlotsInfo.cards[i];
            if(c != cfg.bonusId) {
                continue;
            }
            let idx = i+1;
            let startPos = SlotsFacade.slots.getIdxGlobalPos(idx);
            startPos = topNode.convertToNodeSpaceAR(startPos);
            // 飞行粒子
            let p = cc.instantiate(this.particle);
            p.active = true;
            p.parent = topNode;
            p.position = startPos;
            p.getComponent(cc.ParticleSystem).resetSystem();
            cc.tween(p)
                .to(0.3, {position:endPos})
                .call(()=>{
                    p.removeFromParent();
                })
                .start();
            // 改变symbol
            let symbol = SlotsFacade.slots.GetSymbolByIdx(idx);
            symbol.StartMove();
            symbol.ShowById(4);
        }
        await SlotsFacade.delayTime(0.3);
        // 播放收集特效
        this.spine_collect_effect.node.active = true;
        this.spine_collect_effect.setAnimation(0, "FanKui", false);
        this.goldLionCnt.string = freeInfo.goldLionCnt + "";
        await SlotsFacade.delayTime(0.3);
    },

    /**
     * 加免费次数
     * @returns {Promise<void>}
     */
    async addFreeCnt() {
        let freeSlotsInfo = SlotsFacade.dm.freeSlotsInfo;
        let freeResults = freeSlotsInfo.freeResults;
        if(freeResults.length < 1) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("fgretrigger");
        // 播放免费动画
        freeResults.forEach(itemVo=>{
            let spine = cc.find(`slots${itemVo.slotId+1}/spine_extra_free_cnt`, this.slot_list).getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, `ExtraFG_${itemVo.freeCnt}`, false);
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                spine.node.active = false;
            });
        });
        await SlotsFacade.delayTime(3);
        SlotsFacade.soundMgr.playEffect("triggering");
        // 播放scatter动画
        freeResults.forEach(itemVo=>{
            SlotsFacade.slots.playTriggerAni(itemVo.scatterIdx);
        });
        await SlotsFacade.delayTime(1.5);
        // 飞粒子
        let topNode = SlotsFacade.mainPanel.top_node;
        let endPos = this.free_count.convertToWorldSpaceAR(cc.v2(0,0));
        endPos = topNode.convertToNodeSpaceAR(endPos);
        freeResults.forEach(itemVo=>{
            let startPos = this.slot_list.getChildByName(`slots${itemVo.slotId+1}`).convertToWorldSpaceAR(cc.v2(0,0));
            startPos = topNode.convertToNodeSpaceAR(startPos);
            let p = cc.instantiate(this.particle);
            p.active = true;
            p.parent = topNode;
            p.position = startPos;
            p.getComponent(cc.ParticleSystem).resetSystem();
            cc.tween(p)
                .to(0.3, {position:endPos})
                .call(()=>{
                    p.removeFromParent();
                })
                .start();
        });
        await SlotsFacade.delayTime(0.3);
        // 更新免费次数
        this.updateFreeCnt();
        // 同步bottom 免费次数
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();
        SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total);
    },

    /**
     * 结算金币
     * @returns {Promise<void>}
     */
    async settlementCoin(){
        SlotsFacade.slots.ShowWinTrace();
        let freeInfo = SlotsFacade.dm.freeInfo;
        let freeSlotsInfo = SlotsFacade.dm.freeSlotsInfo;
        // 更新金币
        let nWin = freeSlotsInfo.winCoin;
        let nTotal = freeInfo.winCoin;
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,false, res);
        });
    },

    /**
     * 添加卷轴
     * @returns {Promise<void>}
     */
    async addSlots() {
        let freeInfo = SlotsFacade.dm.freeInfo;
        if(freeInfo.slotCnt == this._slotCnt) {
            return;
        }
        await SlotsFacade.mainPanel.showSceneTransition(2);
        SlotsFacade.soundMgr.playEffect("otherfg");
        this._slotCnt = freeInfo.slotCnt;
        this.showSlot(freeInfo.slotCnt);
        this.updateCollect(true);
    },

    /**
     * 开始旋转
     */
    async startMove() {
        this.updateFreeCnt();
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        if(!this._isEnter) {
            return;
        }
        await this.collect();
        await this.addFreeCnt();
        await this.settlementCoin();
        await this.addSlots();
    },
});
