cc.Class({
    extends: cc.Component,

    properties: {
        panel:cc.Node,
        bg:cc.Node,
        wheel:cc.Node,
        items:[cc.Node],
        proxy:cc.Node,  // 用来产生旋转角度数据的节点空节点即可
        result:cc.Node,
        btn_ok:cc.Node,

        _cbHandler:null,
        _canMove:false,
        _wheelCfg:null, // 转轴相关配置
        _respData:null,
    },

    onLoad() {
        this._wheelCfg = {
            baseRound:10,                    // 基础旋转圈数
            itemsLen:this.items.length,     // 元素个数
            itemHeight:this.items[0].height,// 单个元素高度
            totalHeight:0,                  // 元素总高度
        }
        this._wheelCfg.totalHeight = this._wheelCfg.itemsLen * this._wheelCfg.itemHeight;
    },

    /**
     * 获取旋转角度
     * @returns {number}
     * @private
     */
    _getRotation(itemData) {
        let baseRound = this._wheelCfg.baseRound;
        let angle = baseRound * 360;
        if(itemData.type == 5) {
            let diff = 360/this._wheelCfg.itemsLen/4;
            if(itemData.freeCnt == 15) {
                angle += diff;
            }else {
                angle -= diff;
            }
        }
        return angle;
    },

    /**
     * 开始旋转
     * @private
     */
    async _startWheel() {
        SlotsFacade.soundMgr.playEffect("wheel");
        let resultItemData = this._respData.freeGameInfo.items[this._respData.result.id-1];
        let rotation = this._getRotation(resultItemData);
        this.proxy.rotation = 0;
        // 设置结果
        cc.tween(this.node)
            .delay(3)
            .call(()=>{
                this._setWheelItem(this.items[3], resultItemData);
            })
            .start();
        await new Promise(res=>{
            cc.tween(this.proxy)
                .call(()=> {
                    this._canMove = true;
                })
                .to(7.5, {rotation:rotation}, {easing:"quartInOut"})
                .delay(0.1)
                .call(async ()=>{
                    if(this._respData.result == 1) {
                        SlotsFacade.soundMgr.playEffect("wheelfgx");
                    }else {
                        SlotsFacade.soundMgr.playEffect("wheelfg");
                    }
                    this._canMove = false;
                    await this._showResultEffect();
                    res();
                })
                .start();
        })
        await SlotsFacade.delayTime(0.5);
        let coin = await this._processWheelResult();
        this.close(coin);
    },

    /**
     * 显示中奖结果动画
     * @returns {Promise<void>}
     * @private
     */
    async _showResultEffect() {
        // 改变item父节点
        let item = this.items[3];
        let oldPos = item.position;
        let currPos = this.result.convertToNodeSpaceAR(item.convertToWorldSpaceAR(cc.v2(0,0)));
        item.parent = this.result;
        item.position = currPos;

        // 播放火特效
        let spineEffect = this.result.getChildByName("spine_effect_fire").getComponent(sp.Skeleton);
        spineEffect.node.active = true;
        spineEffect.node.position = currPos;
        spineEffect.setAnimation(0, "D_fire", false);
        spineEffect.setCompleteListener(()=>{
            spineEffect.setCompleteListener(null);
            spineEffect.node.active = false;
        })

        // item内容缩放动画
        let itemLabelCnt = item.getChildByName("label_cnt");
        if(itemLabelCnt.active) {
            cc.tween(itemLabelCnt)
                .to(0.3, {scale:1.2})
                .delay(1.4)
                .to(0.3, {scale:1})
                .start();
        }

        let itemTip = null;
        if(this._respData.freeGameInfo.type == 5) {
            if(this._respData.freeGameInfo.freeCnt == 15) {
                itemTip = cc.find("free/cnt_15", item);
            }else {
                itemTip = cc.find("free/cnt_8", item);
            }
        }else {
            itemTip = item.getChildByName("tip");
        }
        await new Promise(res=>{
            cc.tween(itemTip)
                .to(0.3, {scale:1.2})
                .delay(1.4)
                .to(0.3, {scale:1})
                .call(()=>{
                    // 还原item父节点
                    item.parent = this.wheel;
                    item.position = oldPos;
                    res();
                })
                .start();
        })
    },

    async _processWheelResult() {
        let result = this._respData.result;
        let freeInfo = this._respData.freeGameInfo;
        if(result.type == 1) {
            let coin = freeInfo.items[result.id-1].coin;
            await SlotsFacade.popup.showWinFreeGold(coin);
            return freeInfo.winCoin;
        } else {
            SlotsFacade.dm.SetFreeTime(freeInfo.freeCnt);
            SlotsFacade.dm.SetTotalFree(freeInfo.freeCnt);
            return 0;
        }
    },

    /**
     * 更新卷轴
     * @param dt
     */
    update(dt) {
        if(!this._canMove) {
            return;
        }
        let dist = this.proxy.angle%360/360*this._wheelCfg.totalHeight; // 旋转角度转换成移动距离
        for(let i=0; i<this.items.length; i++) {
            let item =this.items[i];
            let originY = this._wheelCfg.itemHeight/2 + i*this._wheelCfg.itemHeight;
            originY += dist;
            if(originY<-this._wheelCfg.itemHeight/2) {
                originY += this._wheelCfg.totalHeight;
            }
            item.y = originY;
        }
    },

    /**
     * 初始化卷轴
     * @private
     */
    _initWheel() {
        this._canMove = false;
        let itemsCfg = [];
        let hasFree = false;
        SlotsFacade.dm.freeInfo.items.forEach(v=>{
            if(v.type == 5) {
                hasFree = true;
            }else {
                itemsCfg.push(v);
            }
        });
        if(hasFree) {
            itemsCfg.push({"type": 5});
        }
        for(let i=0; i<this.items.length; i++) {
            let item = this.items[i];
            this._setWheelItem(item, itemsCfg[i%itemsCfg.length]);
        }
    },

    /**
     *
     * @param item
     * @param type
     * @param coin
     * @private
     */
    _setWheelItem(item, itemData) {
        let bg = item.getChildByName("bg").getComponent("ImgSwitchCmp");
        let tip = item.getChildByName("tip").getComponent("ImgSwitchCmp");
        tip.node.active = true;
        let label_cnt = item.getChildByName("label_cnt").getComponent("LabelSwitchCmp");
        label_cnt.node.active = false;
        let label_coin = item.getChildByName("label_coin").getComponent(cc.Label);
        label_coin.node.active = false;
        let free = item.getChildByName("free");
        free.active = false;

        let type = itemData.type;
        bg.setIndex(type - 1);
        tip.setIndex(type - 1);
        if(type == 1) {
            label_coin.node.active = true;
            label_coin.string = "$" + Global.FormatNumToComma(itemData.coin);
        } else if(type == 5) {
            free.active = true;
        } else {
            label_cnt.node.active = true;
            label_cnt.setIndex(type-2);
            let diamondInfo = SlotsFacade.dm.getCurrDiamondInfo();
            let cnt = [diamondInfo.blue.freeCnt, diamondInfo.purple.freeCnt, diamondInfo.red.freeCnt][type-2];
            label_cnt.setContent(cnt);
        }
    },

    /**
     * 服务器返回消息
     * @param msg
     */
    onMsg(msg) {
        this._respData = msg.data;
        SlotsFacade.dm.freeInfo = this._respData.freeGameInfo;
        this._startWheel();
    },

    /**
     * 显示开始对话框
     * @returns {Promise<void>}
     * @private
     */
    async _showStart() {
        this.btn_ok.active = true;
        cc.tween(this.btn_ok)
            .to(0.8, {scale:1, opacity:0xff}, {easing:"backOut"})
            .call(()=>{
            })
            .start();
        await SlotsFacade.delayTime(0.8);
        this.btn_ok.on(cc.Node.EventType.TOUCH_END, ()=>{
            SlotsFacade.soundMgr.playEffect("presspin");
            this.btn_ok.off(cc.Node.EventType.TOUCH_END);
            SlotsFacade.dm.reqSubGame({rtype:1});
            cc.tween(this.btn_ok)
                .to(0.5, {scale:0.5, opacity:0}, {easing:"backIn"})
                .call(()=>{
                    this.btn_ok.active = false;
                })
                .start();
        }, this);
    },

    /**
     * @param cb
     */
    async open(cb) {
        await SlotsFacade.mainPanel.showSceneTransition(1);
        SlotsFacade.soundMgr.playBgm("wheelbgm");
        this.panel.active = true;
        this._cbHandler = cb;
        this._initWheel();
        this._showStart();
    },

    async close(coin) {
        if(coin > 0 || this._respData.freeGameInfo.type == 5) {
            await SlotsFacade.mainPanel.showSceneTransition(2);
        }else {
            await SlotsFacade.mainPanel.showSceneTransition(3, SlotsFacade.dm.freeInfo.type);
        }
        SlotsFacade.soundMgr.stopBgm();
        this.panel.active = false;
        if(this._cbHandler) {
            this._cbHandler(coin);
        }
    }
})