/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        freeInfo:null,
        freeSlotsInfo:null,
    },

    init(deskInfo,gameId,gameJackpot) {
        this._super(deskInfo,gameId,gameJackpot);
        this.freeInfo = this._deskInfo.freeGameInfo;
    },

    //注册msg
    RegisterMsg(){
        this._super()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, this);
    },
    UnregisterMsg(){
        this._super()
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, false, this);
    },

    OnRcvNetSpine:function(msg){
        if(msg.code == 200){
            if(msg.collectInfo) {
                this.getDeskInfo().collectInfos[this.GetBetIdx()-1] = msg.collectInfo;
            }
            this.freeInfo = msg.freeGameInfo;
            this.freeSlotsInfo = this._processMapFreeData(msg.freeGameSlots);
        }
        this._super(msg);
    },

    SetSubGameData:function(data){
        this._subGame = data;
    },

    GetSubGameData:function(){
        return this._subGame;
    },

    getSpinData() {
        return this._gameInfo;
    },

    ////////////////////////免费相关///////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.isFistTriggerFree();
    },

    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this._gameInfo.freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    ///////////////////////////收集相关/////////////////
    /**
     * 当前下注是否达到收集的条件
     */
    canCollect() {
        return this.GetBetIdx() >= this.getDeskInfo().needBet;
    },

    /**
     * 获取当前钻石配置信息
     */
    getCurrDiamondInfo() {
        let idx = this.GetBetIdx();
        let collectInfos = this.getDeskInfo().collectInfos;
        let info = collectInfos[idx-1];
        if(!info) {
            info = collectInfos[collectInfos.length-1];
        }
        return info;
    },

    /**
     * 请求子游戏数据51
     * @param param
     */
    reqSubGame(param) {
        let req = {
            c:MsgId.SLOT_SUBGAME_DATA,
            gameid:this._gameId,
            data:param
        };
        cc.vv.NetManager.send(req, true);
    },

    onResp(msg){
        console.log("<<<< reqSubGame-resp: ", msg);
        if(msg.data.rtype == 1){
            SlotsFacade.wheel.onMsg(msg);
        }
    },


    /////////////免费卷轴相关////////////////////////
    /**
     * 处理地图免费游戏数据
     * @param freeGameSlots
     * @returns {null|{randomWilds: null, cards: *[], zjLuXian: *[]}}
     * @private
     */
    _processMapFreeData(freeGameSlots) {
        if(!freeGameSlots) {
            return null;
        }
        let ret = {
            cards:[],           // 牌值
            zjLuXian:[],        // 中奖路线
            freeResults:[],      // 中奖免费次数消息
            winCoin:0,
        }
        for(let i=0; i<freeGameSlots.length; i++) {
            let item = freeGameSlots[i];
            ret.winCoin += item.winCoin;
            ret.cards = ret.cards.concat(item.cards);

            let zjLuXian = item.zjLuXian;
            for(let lx of zjLuXian) {
                this.convertIdx(i, lx.indexs);
            }
            ret.zjLuXian = ret.zjLuXian.concat(zjLuXian);

            let freeResult = item.freeResult;
            if(freeResult && freeResult.freeCnt) {
                this.convertIdx(i, freeResult.scatterIdx)
                ret.freeResults.push({
                    slotId:i,
                    freeCnt:freeResult.freeCnt,
                    scatterIdx:freeResult.scatterIdx
                });
            }
        }
        return ret;
    },
    /**
     * 转换下标
     * @param slotsIdx
     * @param cards
     */
    convertIdx(slotsIdx, cards) {
        for(let i=0; i<cards.length; i++) {
            cards[i] = slotsIdx*20 + cards[i];
        }
    },

    /**
     * 获取中奖路线相关数据
     * @returns {*}
     */
    getZjLuXian() {
        if(this.freeSlotsInfo) {
            return this.freeSlotsInfo.zjLuXian;
        }else {
            return this._gameInfo.zjLuXian;
        }
    },

    getCards() {
        if(this.freeSlotsInfo) {
            return this.freeSlotsInfo.cards;
        }else {
            return this._gameInfo.resultCards;
        }
    }
});
